create extension if not exists "pgcrypto";
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,avatar_url text,birth_date date,loyalty_points int not null default 0,wallet_balance numeric(12,2) not null default 0,loyalty_level text not null default 'Bronze',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('customer','admin','manager','kitchen','driver')),unique(user_id,role));
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,sort_order int not null default 0,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,description text,price numeric(12,2) not null check(price>=0),image_url text,is_active boolean not null default true,options jsonb not null default '{"sizes":[],"addons":[]}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),name text not null,phone text,address text,latitude numeric(10,7),longitude numeric(10,7),opening_time time,closing_time time,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,address_line text not null,city text,postal_code text,latitude numeric(10,7),longitude numeric(10,7),is_default boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.coupons(id uuid primary key default gen_random_uuid(),code text not null unique,discount_type text not null check(discount_type in('percent','fixed')),discount_value numeric(12,2) not null,min_order_amount numeric(12,2) not null default 0,max_discount numeric(12,2),usage_limit int,used_count int not null default 0,starts_at timestamptz,expires_at timestamptz,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default('N'||floor(random()*90000+10000)::text),user_id uuid references auth.users(id) on delete set null,branch_id uuid references public.branches(id) on delete set null,status text not null default 'pending',payment_status text not null default 'pending',order_type text not null check(order_type in('delivery','pickup')),subtotal numeric(12,2) not null default 0,discount numeric(12,2) not null default 0,delivery_fee numeric(12,2) not null default 0,total numeric(12,2) not null default 0,coupon_id uuid references public.coupons(id) on delete set null,address_id uuid references public.addresses(id) on delete set null,address_snapshot text,notes text,scheduled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,quantity int not null check(quantity>0),unit_price numeric(12,2) not null,options jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,provider text,transaction_id text,amount numeric(12,2) not null,status text not null default 'pending',paid_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.favorites(user_id uuid references auth.users(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table if not exists public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,order_id uuid references public.orders(id) on delete set null,rating int not null check(rating between 1 and 5),comment text,status text not null default 'pending',created_at timestamptz not null default now());
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,body text,type text not null default 'system',read_at timestamptz,created_at timestamptz not null default now());
create index if not exists idx_products_category on public.products(category_id);
create index if not exists idx_orders_user on public.orders(user_id);
create index if not exists idx_orders_status on public.orders(status);
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.categories enable row level security;alter table public.addresses enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.favorites enable row level security;alter table public.reviews enable row level security;alter table public.notifications enable row level security;
